const fs=require('fs');
const puppeteer=require('puppeteer-core');
const PRODUCT='83567c124d171bf5d3664b41d8547555a2d196a8';
const base='http://127.0.0.1:8000/';
const vps=[{name:'1920x1080',width:1920,height:1080},{name:'1440x900',width:1440,height:900},{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];
const targets=[{route:'index.html',src:'assets/phase04/film-still-intelligence.webp',name:'homepage-intelligence'},{route:'energy.html',src:'assets/phase08/operations-context.webp',name:'energy-operations'}];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const browser=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage']});fs.mkdirSync('gate-a-final/images',{recursive:true});const out={productSha:PRODUCT,cases:[],failures:[]};for(const target of targets){for(const vp of vps){const p=await browser.newPage();await p.setViewport({width:vp.width,height:vp.height,deviceScaleFactor:1});const requestFailures=[];p.on('requestfailed',r=>requestFailures.push({url:r.url(),error:r.failure()?.errorText||''}));await p.goto(base+target.route,{waitUntil:'load',timeout:30000});await p.evaluate(()=>document.fonts?.ready||Promise.resolve());const selector=`img[src="${target.src}"]`;const exists=await p.$(selector);if(!exists){out.failures.push({target:target.name,vp:vp.name,type:'missing-element'});await p.close();continue}await p.$eval(selector,img=>img.scrollIntoView({block:'center',inline:'nearest'}));let loaded=false;for(let i=0;i<80;i++){loaded=await p.$eval(selector,img=>img.complete&&img.naturalWidth>0&&img.naturalHeight>0);if(loaded)break;await sleep(100)}const state=await p.$eval(selector,img=>{const r=img.getBoundingClientRect();return{complete:img.complete,naturalWidth:img.naturalWidth,naturalHeight:img.naturalHeight,rect:{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height},loading:img.loading,currentSrc:img.currentSrc}});const row={target:target.name,route:target.route,src:target.src,viewport:vp.name,loaded,state,requestFailures};out.cases.push(row);if(!loaded||requestFailures.length)out.failures.push(row);await p.screenshot({path:`gate-a-final/images/${target.name}-${vp.name}.png`,fullPage:false});await p.close()}}fs.writeFileSync('gate-a-final/images/image-load-report.json',JSON.stringify(out,null,2));console.log(JSON.stringify({productSha:PRODUCT,cases:out.cases.length,failures:out.failures},null,2));await browser.close();if(out.cases.length!==10||out.failures.length)process.exit(2)})().catch(e=>{console.error(e);process.exit(1)});
